style.css:
@-moz-document domain("youtube.com") {
/* ==============================
       SADECE YAZILAR
       ============================== */

    /* Video basliklari */
    #video-title,
    #video-title-link {
        color: #b9dcf5 !important;
    }

    /* Onerilen videolar */
    ytd-compact-video-renderer #video-title {
        color: #f3bfd6 !important;
    }

    /* Kanal isimleri */
    #channel-name,
    #channel-name a,
    ytd-channel-name a {
        color: #f3bfd6 !important;
    }

    /* Izlenme / tarih */
    #metadata-line,
    #metadata-line span,
    ytd-video-meta-block span {
        color: #9ebed5 !important;
    }

    /* Video sayfasi basligi */
    ytd-watch-metadata h1,
    #above-the-fold h1 {
        color: #c9e5f7 !important;
    }

    /* Aciklama */
    #description,
    #description-inline-expander {
        color: #f8d9e7 !important;
    }

    /* Sol menu */
    ytd-guide-entry-renderer yt-formatted-string {
        color: #f3bfd6 !important;
    }

    /* Yorumlar */
    #content-text {
        color: #f3bfd6 !important;
    }

    /* Arama kutusu yazisi */
    #search-input input {
        color: #f8d9e7 !important;
    }
}
